mapper.select:
SELECT p.*, o.name AS owner_name, t.name AS tenant_name FROM t_parking p LEFT JOIN t_owner o ON p.owner_id = o.id LEFT JOIN t_tenant t ON p.tenant_id = t.id
AND (p.parking_no LIKE CONCAT('%', #{queryString}, '%') OR p.area LIKE CONCAT('%', #{queryString}, '%') OR o.name LIKE CONCAT('%', #{queryString}, '%') OR t.name LIKE CONCAT('%', #{queryString}, '%'))
AND p.type = #{type}
AND p.status = #{status}
ORDER BY p.parking_no

mapper.update:
UPDATE t_parking
parking_no = #{parkingNo}, area = #{area}, type = #{type}, size = #{size}, owner_id = #{ownerId}, tenant_id = #{tenantId}, monthly_rent = #{monthlyRent}, status = #{status}, remark = #{remark},
WHERE id = #{id}
